#define _GNU_SOURCE

#include <dlfcn.h>
#include <errno.h>
#include <limits.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <unistd.h>

typedef ssize_t (*readlink_fn)(const char *, char *, size_t);
typedef ssize_t (*readlinkat_fn)(int, const char *, char *, size_t);

static int is_current_process_exe(const char *path) {
    static const char prefix[] = "/proc/";
    static const char suffix[] = "/exe";
    char *end = NULL;
    long parsed;

    if (path == NULL || strncmp(path, prefix, sizeof(prefix) - 1) != 0) {
        return 0;
    }
    errno = 0;
    parsed = strtol(path + sizeof(prefix) - 1, &end, 10);
    return errno == 0 && end != path + sizeof(prefix) - 1
        && strcmp(end, suffix) == 0 && parsed == (long)getpid();
}

ssize_t readlink(const char *path, char *buffer, size_t size) {
    static readlink_fn real_readlink = NULL;
    if (real_readlink == NULL) {
        real_readlink = (readlink_fn)dlsym(RTLD_NEXT, "readlink");
    }
    if (is_current_process_exe(path)) {
        path = "/proc/self/exe";
    }
    return real_readlink(path, buffer, size);
}

ssize_t readlinkat(int directory, const char *path, char *buffer, size_t size) {
    static readlinkat_fn real_readlinkat = NULL;
    if (real_readlinkat == NULL) {
        real_readlinkat = (readlinkat_fn)dlsym(RTLD_NEXT, "readlinkat");
    }
    if (is_current_process_exe(path)) {
        path = "/proc/self/exe";
    }
    return real_readlinkat(directory, path, buffer, size);
}

